<script setup lang="ts">
// Home / Dashboard (generated by engineering-platform frontend-auth asset)
// V06-WORK-003B — Dashboard Composition 2.0 (Visual Refinement)
//   - hero: soft tinted gradient surface (not a plain white panel) + status
//   - KPI cards: 3 layers — accent icon surface / metric / context+trend
//   - business overview: compact widget rows with indicators, not table rows
//   - activity chart: card with clear hierarchy, weaker grid, gradient bars
//   - recent activity: timeline / activity feed language
// Self-contained (tokens + Element Plus only) so it renders in ANY project
// that includes frontend-auth. Data is deterministic demo data.
import { computed } from 'vue';
import { useAuthStore } from '../stores/auth';

const auth = useAuthStore();

const greeting = computed(() => {
  const hour = new Date().getHours();
  if (hour < 6) return 'Good night';
  if (hour < 12) return 'Good morning';
  if (hour < 18) return 'Good afternoon';
  return 'Good evening';
});

// ---- deterministic demo data (stable, no backend) ----
const kpis = [
  { label: 'Active modules', value: '12', delta: '+2 this quarter', tone: 'up', accent: 'indigo', marker: 'M', sub: '8 enterprise · 4 generic' },
  { label: 'Open orders', value: '1,284', delta: '+8.2% vs last week', tone: 'up', accent: 'sky', marker: 'O', sub: 'across 9 departments' },
  { label: 'On-time delivery', value: '94.6%', delta: '+1.1% vs last week', tone: 'up', accent: 'emerald', marker: 'D', sub: 'rolling 30 days' },
  { label: 'Pending approvals', value: '23', delta: '3 need attention', tone: 'down', accent: 'amber', marker: 'A', sub: 'awaiting your review' },
] as const;

const overview = [
  { label: 'Business modules', value: '12', hint: '8 enterprise + 4 generic', accent: 'indigo', pct: 75 },
  { label: 'Users', value: '128', hint: '5 roles · 9 departments', accent: 'sky', pct: 64 },
  { label: 'Dictionary types', value: '18', hint: '142 items enabled', accent: 'violet', pct: 82 },
  { label: 'Menus', value: '24', hint: 'directory + leaf nodes', accent: 'cyan', pct: 58 },
] as const;

const activity = [
  { title: 'Supplier SUP-001 enabled', meta: 'Inventory module', time: '09:12', tone: 'ok', icon: 'CircleCheck' },
  { title: 'CustomerLite record created', meta: 'By ops-lead', time: '08:47', tone: 'ok', icon: 'Plus' },
  { title: 'WarehouseLite capacity updated', meta: 'WMS sync', time: '08:31', tone: 'info', icon: 'Refresh' },
  { title: 'Role "sales-manager" permissions changed', meta: 'By admin', time: '07:55', tone: 'warn', icon: 'Warning' },
  { title: 'Dictionary supplier_status refreshed', meta: 'System job', time: '07:20', tone: 'info', icon: 'Refresh' },
] as const;

// lightweight bar chart (pure CSS, deterministic)
const chart = [
  { label: 'Mon', value: 42 },
  { label: 'Tue', value: 58 },
  { label: 'Wed', value: 51 },
  { label: 'Thu', value: 76 },
  { label: 'Fri', value: 64 },
  { label: 'Sat', value: 38 },
  { label: 'Sun', value: 29 },
] as const;
const maxChart = Math.max(...chart.map((c) => c.value));
</script>

